def bottleneck_path(adj, fitness, src, tgt):
    import math
    bn = {v: -math.inf for v in adj}
    bn[src] = fitness[src]
    visited = set()
    for _ in range(len(adj)):
        v = max((u for u in adj if u not in visited), key=lambda u: bn[u])
        if v == tgt: break
        visited.add(v)
        for u in adj[v]:
            bn[u] = max(bn[u], min(bn[v], fitness[u]))
    return bn[tgt]

def maxmin_matpow(M, n, k):
    import math
    R = [[(-math.inf if i!=j else math.inf) for j in range(n)] for i in range(n)]
    for _ in range(k):
        N = [[-math.inf]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for l in range(n):
                    N[i][j] = max(N[i][j], min(R[i][l], M[l][j]))
        R = N
    return R
